const api=async(url,method='GET',body)=>{const r=await fetch(url+(method==='GET'?(url.includes('?')?'&':'?')+'token='+encodeURIComponent(token()):''),{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify({...body,token:token()})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Something went wrong.');return d;};
