 closePostCamera();const overlay=document.createElement('div');overlay.id='aamPostCameraOverlay';overlay.className='aam-post-camera-overlay';overlay.innerHTML='<video id="aamPostLiveCamera" autoplay playsinline muted></video><div class="aam-post-camera-top"><button type="button" onclick="AAMSocial.closePostCamera()" aria-label="Close camera">×</button><span>Camera</span><button type="button" id="aamPostFlipCamera" aria-label="Switch camera">↻</button></div><div class="aam-post-camera-bottom"><button type="button" class="aam-camera-recent" id="aamCameraRecent" aria-label="Choose recent photo or video">▧</button><button type="button" id="aamPostRecordToggle" aria-label="Record video">●</button><button type="button" id="aamPostCapturePhoto" aria-label="Take photo">●</button><span id="aamPostCameraStatus">Photo</span></div>';
