async function startPostCamera(facing){try{aamPostCameraStream=await navigator.mediaDevices.getUserMedia({audio:true,video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:1920}}});const v=document.getElementById('aamPostLiveCamera');if(v){v.srcObject=aamPostCameraStream;await v.play().catch(()=>{});}const photo=document.getElementById('aamPostCapturePhoto'),record=document.getElementById('aamPostRecordToggle'),flip=document.getElementById('aamPostFlipCamera');if(photo)photo.onclick=capturePostPhoto;if(record)record.onclick=togglePostRecording;if(flip)flip.onclick=async()=>{const next=facing==='environment'?'user':'environment';closePostCamera();await openPostCameraFacing(next);};const recent=document.getElementById('aamCameraRecent');if(recent)recent.onclick=()=>{closePostCamera();openPostGallery();};}catch(e){closePostCamera();notice(e.name==='NotAllowedError'?'Allow camera access to take a photo or video.':'Camera is unavailable. You can choose media from your gallery instead.');}}
async function openPostCameraFacing(facing){const overlay=document.createElement('div');overlay.id='aamPostCameraOverlay';overlay.className='aam-post-camera-overlay';overlay.innerHTML='<video id="aamPostLiveCamera" autoplay playsinline muted></video><div class="aam-post-camera-top"><button type="button" onclick="AAMSocial.closePostCamera()" aria-label="Close camera">×</button><span>Camera</span><button type="button" id="aamPostFlipCamera" aria-label="Switch camera">↻</button></div><div class="aam-post-camera-bottom"><button type="button" class="aam-camera-recent" id="aamCameraRecent" aria-label="Choose recent photo or video">▧</button><button type="button" id="aamPostRecordToggle" aria-label="Record video">●</button><button type="button" id="aamPostCapturePhoto" aria-label="Take photo">●</button><span id="aamPostCameraStatus">Photo</span></div>';document.body.appendChild(overlay);await startPostCamera(facing);}
function closePostCamera(){if(aamPostRecorder&&aamPostRecorder.state!=='inactive')aamPostRecorder.stop();aamPostRecorder=null;aamPostRecordedChunks=[];if(aamPostCameraStream){aamPostCameraStream.getTracks().forEach(t=>t.stop());aamPostCameraStream=null;}document.getElementById('aamPostCameraOverlay')?.remove();}
function capturePostPhoto(){const video=document.getElementById('aamPostLiveCamera');if(!video||!video.videoWidth)return notice('Camera is still starting. Try again in a moment.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob)return notice('Could not capture the photo.');postFileChanged({target:{files:[new File([blob],'camera-photo.jpg',{type:'image/jpeg',lastModified:Date.now()})]}});closePostCamera();},'image/jpeg',.92);}
function togglePostRecording(){if(!aamPostCameraStream)return;const button=document.getElementById('aamPostRecordToggle'),status=document.getElementById('aamPostCameraStatus');if(aamPostRecorder?.state==='recording'){aamPostRecorder.stop();if(button)button.textContent='●';if(status)status.textContent='Saving video…';return;}const mime=['video/mp4;codecs=avc1.42E01E','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported?.(x))||'';try{aamPostRecordedChunks=[];aamPostRecorder=new MediaRecorder(aamPostCameraStream,mime?{mimeType:mime}:undefined);aamPostRecorder.ondataavailable=e=>{if(e.data?.size)aamPostRecordedChunks.push(e.data);};aamPostRecorder.onstop=()=>{const type=aamPostRecorder?.mimeType||'video/webm',blob=new Blob(aamPostRecordedChunks,{type});if(blob.size)postFileChanged({target:{files:[new File([blob],'camera-video.'+(type.includes('mp4')?'mp4':'webm'),{type,lastModified:Date.now()})]}});closePostCamera();};aamPostRecorder.start(500);if(button)button.textContent='■';if(status)status.textContent='Recording…';}catch(e){notice('Video recording is not supported by this browser. Use the gallery instead.');}}
function openPostGallery(){document.getElementById('aamPostGalleryInput')?.click();}
function postFileChanged(event){const file=event.target.files?.[0];if(!file)return;selectedPostFile=file;if(postPreviewUrl)URL.revokeObjectURL(postPreviewUrl);postPreviewUrl=URL.createObjectURL(file);const preview=document.getElementById('aamPostPreview');if(preview)preview.innerHTML=file.type.startsWith('video/')?'<video src="'+postPreviewUrl+'" controls playsinline></video>':'<img src="'+postPreviewUrl+'" alt="Selected post">';const recent=document.getElementById('aamPostRecent');if(recent)recent.innerHTML=file.type.startsWith('image/')?'<img src="'+postPreviewUrl+'" alt="Recent photo">':'▶';const button=document.getElementById('aamPostPublish');if(button)button.disabled=false;}
window.aamSelectedSounds=window.aamSelectedSounds||{post:null,status:null,admin:null};window.aamAudiusSearchResults=window.aamAudiusSearchResults||{};
function soundPickerMarkup(slot){return '<section class="aam-sound-picker"><label>Add a sound from Audius (optional)</label><div class="aam-sound-search-row"><input class="aam-social-field" id="aamSoundQuery_'+slot+'" maxlength="100" placeholder="Search songs or artists"><button type="button" class="aam-social-btn secondary" onclick="AAMSocial.searchAudiusSounds(\''+slot+'\')">Search</button></div><div id="aamSoundResults_'+slot+'" class="aam-sound-results"></div><div id="aamSoundSelected_'+slot+'" class="aam-sound-selected">No sound selected</div></section>';}
function soundFields(slot){const t=window.aamSelectedSounds?.[slot];return t?{sound_track_id:t.id,sound_title:t.title,sound_artist:t.artist,sound_artwork_url:t.artwork||''}:{sound_track_id:null,sound_title:'',sound_artist:'',sound_artwork_url:''};}
async function searchAudiusSounds(slot){const input=document.getElementById('aamSoundQuery_'+slot),out=document.getElementById('aamSoundResults_'+slot),query=input?.value?.trim()||'';if(query.length<2)return notice('Enter at least two letters to search Audius.');if(out)out.innerHTML='<p class="aam-social-muted">Searching Audius…</p>';try{const auth=slot==='admin'?adminToken():token(),url='/.netlify/functions/social-audius?query='+encodeURIComponent(query)+'&token='+encodeURIComponent(auth),r=await fetch(url),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Audius search failed.');window.aamAudiusSearchResults[slot]=d.tracks||[];if(!out)return;out.innerHTML=(d.tracks||[]).map((t,i)=>'<div class="aam-sound-result">'+(t.artwork?'<img src="'+esc(t.artwork)+'" alt="">':'<span class="aam-sound-art">♫</span>')+'<span><strong>'+esc(t.title)+'</strong><small>'+esc(t.artist)+'</small></span><button type="button" class="aam-social-btn secondary" onclick="AAMSocial.chooseAudiusSound(\''+slot+'\','+i+')">Use sound</button></div>').join('')||'<p class="aam-social-muted">No matching tracks found.</p>';}catch(e){if(out)out.innerHTML='<p class="aam-social-muted">'+esc(e.message)+'</p>';}}
function chooseAudiusSound(slot,index){const t=(window.aamAudiusSearchResults?.[slot]||[])[Number(index)];if(!t)return;window.aamSelectedSounds[slot]=t;const out=document.getElementById('aamSoundSelected_'+slot);if(out)out.innerHTML='<div class="aam-sound-chosen">'+(t.artwork?'<img src="'+esc(t.artwork)+'" alt="">':'<span class="aam-sound-art">♫</span>')+'<span><strong>'+esc(t.title)+'</strong><small>'+esc(t.artist)+'</small></span><button type="button" class="aam-social-btn secondary" onclick="AAMSocial.clearAudiusSound(\''+slot+'\')">Remove</button></div><audio controls preload="none" src="'+audiusStreamUrl(t.id,slot)+'"></audio>';}
