function audiusStreamUrl(id,slot){const auth=slot==='admin'?adminToken():token()||adminToken();return '/.netlify/functions/social-audius?action=stream&id='+encodeURIComponent(id)+'&token='+encodeURIComponent(auth);}
function soundPlayerHtml(item){if(!item?.sound_track_id)return '';const art=item.sound_artwork_url?'<img src="'+esc(item.sound_artwork_url)+'" alt="">':'<span class="aam-sound-art">♫</span>';return '<div class="aam-social-soundtrack">'+art+'<span><strong>'+esc(item.sound_title||'Audius track')+'</strong><small>'+esc(item.sound_artist||'Audius')+'</small></span><audio controls preload="none" src="'+audiusStreamUrl(item.sound_track_id,'post')+'"></audio></div>';}
async function statusPage(){loadingPage('Loading Status…','status');try{const d=await api('/.netlify/functions/social-status'),groups=new Map();for(const x of d.statuses||[]){if(!groups.has(x.customer_id))groups.set(x.customer_id,{name:x.owner_name,avatar:x.avatar_url,items:[]});groups.get(x.customer_id).items.push(x);}const groupHtml=[...groups.entries()].map(([id,g])=>'<button class="aam-social-status-person" onclick="AAMSocial.openStatusGroup(&quot;'+esc(id)+'&quot;)">'+(g.avatar?'<img src="'+esc(g.avatar)+'" alt="">':'<span class="aam-status-avatar">'+esc((g.name||'F').slice(0,1).toUpperCase())+'</span>')+'<span><strong>'+esc(g.name)+'</strong><small>'+(id===customer()?'My Status':g.items.some(x=>!x.viewed)?'New Status':'Viewed')+'</small></span><b>'+(g.items.some(x=>!x.viewed)?'●':'')+'</b></button>').join('');window.aamStatusGroups=[...groups.entries()];mount('<div class="aam-social-card"><h2>STATUS</h2><div class="aam-social-actions"><button class="aam-social-btn" onclick="AAMSocial.newTextStatus()">＋ Text Status</button><button class="aam-social-btn secondary" onclick="AAMSocial.pickStatusFile()">＋ Photo / Video</button></div>'+soundPickerMarkup('status')+'<input id="aamStatusFile" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" hidden onchange="AAMSocial.createMediaStatus()"><div id="aamStatusGroups">'+(groupHtml||'<p class="aam-social-muted">No Status updates yet. Add your first one.</p>')+'</div></div>','status');}catch(e){mount('<div class="aam-social-card"><h2>STATUS</h2><p>'+esc(e.message)+'</p><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'home\')">← Home</button></div>','status');}}
function newTextStatus(){const body=prompt('Write your Status (up to 700 characters):');if(body===null)return;if(!body.trim())return notice('Write something first.');api('/.netlify/functions/social-status','POST',{action:'create',status_type:'text',body,...soundFields('status')}).then(()=>{notice('Status published. It will expire after 24 hours.');statusPage();}).catch(e=>notice(e.message));}
async function uploadSocialMedia(signed,file){if(signed?.provider==='cloudflare'){if(!signed.upload_url||!signed.path)throw new Error('Cloudflare did not return a valid upload URL.');if(file.size>180*1024*1024)throw new Error('This video is larger than 180 MB. Please choose a smaller video.');const form=new FormData();form.append('file',file,file.name||'video.mp4');const r=await fetch(signed.upload_url,{method:'POST',body:form,signal:AbortSignal.timeout(180000)});if(!r.ok)throw new Error('Cloudflare video upload failed ('+r.status+'). Please try again.');return signed.path;}const up=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;return signed.path;}
async function createMediaStatus(){const file=document.getElementById('aamStatusFile')?.files?.[0];if(!file)return;try{const signed=await api('/.netlify/functions/social-status','POST',{action:'sign_upload',mime_type:file.type});await uploadSocialMedia(signed,file);await api('/.netlify/functions/social-status','POST',{action:'create',status_type:file.type.startsWith('video/')?'video':'image',media_path:signed.path,...soundFields('status')});notice('Status published. It will expire after 24 hours.');statusPage();}catch(e){notice(e.message);}}
function openStatusGroup(id){const g=(window.aamStatusGroups||[]).find(x=>x[0]===id);if(!g)return;window.aamStatusItems=g[1].items;window.aamStatusIndex=0;showStatusItem();}
function showStatusItem(){const items=window.aamStatusItems||[],i=window.aamStatusIndex||0,x=items[i];if(!x)return statusPage();const own=x.customer_id===customer();if(!own)api('/.netlify/functions/social-status','POST',{action:'view',status_id:x.id}).catch(()=>{});const content=x.status_type==='text'?'<div class="aam-status-text" style="background:'+esc(x.background||'#087443')+'">'+esc(x.body)+'</div>':x.status_type==='video'?(x.media_provider==='cloudflare'?'<div class="aam-status-cloudflare"><iframe src="'+esc(x.media_url)+'" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe></div>':'<video class="aam-status-fullmedia" controls autoplay playsinline src="'+esc(x.media_url)+'"></video>'):'<img class="aam-status-fullmedia" src="'+esc(x.media_url)+'" alt="Status">';mount('<div class="aam-social-card aam-status-viewer"><div class="aam-status-progress">'+items.map((_,n)=>'<i class="'+(n<=i?'done':'')+'"></i>').join('')+'</div><div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'status\')">←</button><strong>'+esc(x.owner_name)+'</strong><span class="aam-social-muted">'+new Date(x.created_at).toLocaleString()+'</span></div>'+content+soundPlayerHtml(x)+'<div class="aam-social-actions">'+(own?'<button class="aam-social-btn secondary" onclick="AAMSocial.deleteStatus(&quot;'+esc(x.id)+'&quot;)">Delete my Status</button>':'')+'<button class="aam-social-btn" onclick="AAMSocial.nextStatus()">'+(i<items.length-1?'Next':'Done')+'</button></div></div>','status');}
function nextStatus(){window.aamStatusIndex=(window.aamStatusIndex||0)+1;showStatusItem();}
