async function captureVideoThumbnail(file){return new Promise(resolve=>{const video=document.createElement('video'),url=URL.createObjectURL(file),canvas=document.createElement('canvas');let done=false;const finish=value=>{if(done)return;done=true;URL.revokeObjectURL(url);resolve(value);};video.muted=true;video.playsInline=true;video.preload='metadata';video.onloadedmetadata=()=>{try{video.currentTime=Math.min(.5,Math.max(0,(video.duration||1)/3));}catch(e){finish(null);}};video.onseeked=()=>{try{canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>finish(blob),'image/jpeg',.78);}catch(e){finish(null);}};video.onerror=()=>finish(null);video.src=url;setTimeout(()=>finish(null),8000);});}
async function publish(){const textMode=!document.getElementById('aamTextPostEditor')?.hidden;const file=selectedPostFile||document.getElementById('aamPostCameraInput')?.files?.[0]||document.getElementById('aamPostGalleryInput')?.files?.[0];const status=document.getElementById('aamUploadStatus');try{if(textMode){const body=document.getElementById('aamTextPostBody')?.value?.trim()||'';if(!body)return notice('Write something first.');if(status)status.textContent='Publishing…';await api('/.netlify/functions/social-feed','POST',{action:'publish_text_post',body,background_color:selectedPostBackground,...soundFields('post')});notice('Your post has been published.');home();return;}if(!file)return notice('Take a photo or choose a video.');if(status)status.textContent='Preparing…';const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_upload',mime_type:file.type});await uploadSocialMedia(signed,file);let thumbnailPath=null;if(file.type.startsWith('video/')){const thumb=await captureVideoThumbnail(file);if(thumb){const st=await api('/.netlify/functions/social-feed','POST',{action:'sign_thumbnail_upload'}),tu=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(st.path,st.token,thumb,{contentType:'image/jpeg',upsert:false});if(tu.error)throw tu.error;thumbnailPath=st.path;}}if(status)status.textContent='Publishing…';await api('/.netlify/functions/social-feed','POST',{action:'publish_post',media_path:signed.path,thumbnail_path:thumbnailPath,mime_type:file.type,caption:document.getElementById('aamCaption')?.value||'',...soundFields('post')});notice('Your post has been published.');home();}catch(e){if(status)status.textContent=e.message;else notice(e.message);}}
async function profile(){loadingPage('Loading your profile…','profile');try{const d=await api('/.netlify/functions/social-core');const p=d.profile||{},prefs=d.preferences||{};notificationSoundChoice=Number(prefs.notification_sound||1);const sounds=Array.from({length:15},(_,i)=>'<option value="'+(i+1)+'"'+(Number(prefs.notification_sound||1)===i+1?' selected':'')+'>Calm sound '+(i+1)+'</option>').join('');const wallpapers=['default',...Array.from({length:20},(_,i)=>'theme-'+String(i+1).padStart(2,'0')),'custom',...(prefs.custom_wallpaper_path?[]:[])].map((v)=>'<option value="'+v+'"'+((prefs.chat_wallpaper||'default')===v?' selected':'')+'>'+(v==='default'?'Default':'Wallpaper '+v.slice(-2))+'</option>').join('');mount('<section class="aam-profile-hero"><div class="aam-profile-avatar-wrap">'+(p.avatar_url?'<img class="aam-social-avatar aam-profile-avatar" src="'+esc(p.avatar_url)+'" alt="Profile picture">':'<div class="aam-profile-avatar aam-profile-avatar-empty">'+esc((p.display_name||customer()||'A').slice(0,1).toUpperCase())+'</div>')+'<button type="button" class="aam-avatar-camera" onclick="AAMSocial.openProfileCamera()" aria-label="Take profile photo">📷</button></div><div><span class="aam-social-muted">YOUR PROFILE</span><h2>'+esc(p.display_name||'My Profile')+'</h2><p class="aam-social-muted">Your creator identity and account settings</p></div></section><div class="aam-social-card"><h2>Profile photo</h2><div class="aam-photo-pickers"><button class="aam-social-btn" type="button" onclick="AAMSocial.openProfileCamera()">📷 Take photo</button><button class="aam-social-btn secondary" type="button" onclick="document.getElementById(\'aamAvatarFile\').click()">▧ Choose photo</button></div><input class="aam-file-hidden" id="aamAvatarFile" type="file" accept="image/jpeg,image/png,image/webp" onchange="AAMSocial.updateAvatar()"><div class="aam-social-balance">'+Number(d.coin_balance||0).toLocaleString()+' total coins</div><p>Free coins: <strong>'+Number(d.free_coin_balance||0).toLocaleString()+'</strong> · Money Coins: <strong>'+Number(d.purchased_coin_balance||0).toLocaleString()+'</strong></p><p class="aam-social-muted">'+formatCount(d.followers||0)+' followers · '+formatCount(d.following||0)+' following · '+formatCount(d.profile_views||0)+' views</p><p class="aam-social-muted">Referral number: '+esc(p.referral_code||'Preparing…')+'</p><input type="hidden" id="aamReferralCode" value="'+esc(p.referral_code||'')+'"><input type="hidden" id="aamReferralUrl" value="'+esc(window.location.origin+'/?referral='+(p.referral_code||''))+'"><div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.copyReferralCode()">Copy Referral Number</button><button class="aam-social-btn secondary" onclick="AAMSocial.copyReferralLink()">Copy Referral Link</button></div><p class="aam-social-muted">Profile ID: '+esc(p.customer_id||'')+'</p><input type="hidden" id="aamProfileId" value="'+esc(p.customer_id||'')+'"><input type="hidden" id="aamProfileUrl" value="'+esc(window.location.origin+'/?creator='+(p.customer_id||''))+'"><div class="aam-social-actions"><button class="aam-social-btn secondary" onclick="AAMSocial.copyProfileId()">Copy Profile ID</button><button class="aam-social-btn secondary" onclick="AAMSocial.copyProfileLink()">Copy Profile Link</button><button class="aam-social-btn secondary" onclick="AAMSocial.shareProfile()">Share Profile</button></div><label>Display name</label><input class="aam-social-field" id="aamDisplayName" maxlength="40" value="'+esc(p.display_name||'')+'"><label>Bio</label><textarea class="aam-social-field" id="aamBio" maxlength="300">'+esc(p.bio||'')+'</textarea><label class="aam-social-check"><input type="checkbox" id="aamPrivateProfile"'+(p.is_private?' checked':'')+'> Private profile</label><label class="aam-social-check"><input type="checkbox" id="aamCommentsEnabled"'+(p.comments_enabled===false?'':' checked')+'> Allow comments on my posts</label><button class="aam-social-btn" onclick="AAMSocial.saveProfile()">Save profile</button></div><div class="aam-social-card"><h3>Notification and chat settings</h3><label>Notification sound</label><select class="aam-social-field" id="aamSoundChoice">'+sounds+'</select><button class="aam-social-btn secondary" onclick="AAMSocial.previewSound()">Preview sound</button><label>Chat wallpaper</label><select class="aam-social-field" id="aamWallpaperChoice">'+wallpapers+'</select><input type="hidden" id="aamExistingWallpaperPath" value="'+esc(prefs.custom_wallpaper_path||'')+'"><label>Upload a custom wallpaper</label><input class="aam-social-field" type="file" id="aamCustomWallpaper" accept="image/jpeg,image/png,image/webp"><h4>Notification preferences</h4><label class="aam-social-check"><input type="checkbox" id="aamPrefViews"'+(prefs.profile_view_notifications===false?'':' checked')+'> Profile views</label><label class="aam-social-check"><input type="checkbox" id="aamPrefFollows"'+(prefs.follow_notifications===false?'':' checked')+'> New followers</label><label class="aam-social-check"><input type="checkbox" id="aamPrefLikes"'+(prefs.like_notifications===false?'':' checked')+'> Likes</label><label class="aam-social-check"><input type="checkbox" id="aamPrefComments"'+(prefs.comment_notifications===false?'':' checked')+'> Comments</label><label class="aam-social-check"><input type="checkbox" id="aamPrefShares"'+(prefs.share_notifications===false?'':' checked')+'> Shares</label><label class="aam-social-check"><input type="checkbox" id="aamPrefMessages"'+(prefs.message_notifications===false?'':' checked')+'> Messages</label><label class="aam-social-check"><input type="checkbox" id="aamPrefProfileUpdates"'+(prefs.profile_update_notifications===false?'':' checked')+'> Profile picture updates</label><button class="aam-social-btn" onclick="AAMSocial.savePreferences()">Save settings</button></div><div class="aam-social-card"><h3>All Ads Manager tools</h3><button class="aam-social-btn secondary" onclick="AAMSocial.open(\'dashboard\')">Open services dashboard</button></div>','profile');}catch(e){notice(e.message);}}
async function uploadAvatarBlob(file){if(!file)return notice('Choose or take a profile photo first.');try{const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_avatar_upload',mime_type:file.type}),up=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;await api('/.netlify/functions/social-core','POST',{action:'update_avatar',avatar_path:signed.path});notice('Profile photo updated.');profile();}catch(e){notice(e.message);}}
async function updateAvatar(){const file=document.getElementById('aamAvatarFile')?.files?.[0];return uploadAvatarBlob(file);}
async function openProfileCamera(){if(!navigator.mediaDevices?.getUserMedia){document.getElementById('aamAvatarFile')?.click();return notice('Camera is unavailable. Choose a photo from your gallery.');}try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'user'}},audio:false});document.getElementById('aamProfileCameraModal')?.remove();const modal=document.createElement('div');modal.id='aamProfileCameraModal';modal.className='aam-profile-camera-modal';modal.innerHTML='<div class="aam-profile-camera-panel"><header><button type="button" aria-label="Close camera" id="aamProfileCameraClose">←</button><strong>Profile photo</strong><span></span></header><video id="aamProfileCameraVideo" autoplay playsinline muted></video><div class="aam-profile-camera-actions"><button type="button" id="aamProfileCapture">● Capture photo</button><button type="button" id="aamProfileUseGallery">▧ Gallery</button></div></div>';document.body.appendChild(modal);const video=modal.querySelector('video');video.srcObject=stream;await video.play();const stop=()=>{stream.getTracks().forEach(t=>t.stop());modal.remove();};modal.querySelector('#aamProfileCameraClose').onclick=stop;modal.querySelector('#aamProfileUseGallery').onclick=()=>{stop();document.getElementById('aamAvatarFile')?.click();};modal.querySelector('#aamProfileCapture').onclick=()=>{if(!video.videoWidth)return notice('Camera is starting. Try again.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{stop();if(blob)uploadAvatarBlob(new File([blob],'profile-photo.jpg',{type:'image/jpeg'}));},'image/jpeg',.92);};}catch(e){notice(e.name==='NotAllowedError'?'Allow camera access to take your profile photo.':'Camera unavailable. Choose a photo from your gallery.');}}
async function saveProfile(){try{await api('/.netlify/functions/social-core','POST',{action:'update_profile',display_name:document.getElementById('aamDisplayName')?.value||'',bio:document.getElementById('aamBio')?.value||'',is_private:!!document.getElementById('aamPrivateProfile')?.checked,comments_enabled:!!document.getElementById('aamCommentsEnabled')?.checked});notice('Profile settings saved.');}catch(e){notice(e.message);}}
async function savePreferences(){try{let wallpaper=document.getElementById('aamWallpaperChoice')?.value||'default',path=wallpaper==='custom'?(document.getElementById('aamExistingWallpaperPath')?.value||''):null;const file=document.getElementById('aamCustomWallpaper')?.files?.[0];if(file){const signed=await api('/.netlify/functions/social-feed','POST',{action:'sign_wallpaper_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;path=signed.path;wallpaper='custom';}if(wallpaper==='custom'&&!path)throw new Error('Choose a wallpaper image first.');await api('/.netlify/functions/social-core','POST',{action:'update_preferences',notification_sound:Number(document.getElementById('aamSoundChoice')?.value||1),chat_wallpaper:wallpaper,custom_wallpaper_path:path});await api('/.netlify/functions/social-core','POST',{action:'update_notification_preferences',profile_view_notifications:!!document.getElementById('aamPrefViews')?.checked,follow_notifications:!!document.getElementById('aamPrefFollows')?.checked,like_notifications:!!document.getElementById('aamPrefLikes')?.checked,comment_notifications:!!document.getElementById('aamPrefComments')?.checked,share_notifications:!!document.getElementById('aamPrefShares')?.checked,message_notifications:!!document.getElementById('aamPrefMessages')?.checked,profile_update_notifications:!!document.getElementById('aamPrefProfileUpdates')?.checked});notice('Chat and notification settings saved.');}catch(e){notice(e.message);}}
function previewSound(){if(!window.AudioContext&&!window.webkitAudioContext)return notice('Sound preview is not supported on this device.');const id=Number(document.getElementById('aamSoundChoice')?.value||1),ctx=new (window.AudioContext||window.webkitAudioContext)(),notes=[440,494,523,587,659,392,349,330,294,262,698,784,880,988,1047],freq=notes[(id-1)%notes.length];[0,0.16].forEach((delay,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq*(i?1.25:1);g.gain.setValueAtTime(0.0001,ctx.currentTime+delay);g.gain.exponentialRampToValueAtTime(0.08,ctx.currentTime+delay+0.025);g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+delay+0.13);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+0.14);});setTimeout(()=>ctx.close(),600);}
function playNotificationSound(id){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),notes=[440,494,523,587,659,392,349,330,294,262,698,784,880,988,1047],freq=notes[(Number(id||1)-1)%notes.length];[0,.17].forEach((delay,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=freq*(i?1.18:1);g.gain.setValueAtTime(.0001,ctx.currentTime+delay);g.gain.exponentialRampToValueAtTime(.035,ctx.currentTime+delay+.03);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+delay+.19);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+delay);o.stop(ctx.currentTime+delay+.2);});setTimeout(()=>ctx.close(),600);}catch(e){}}
async function updateNotificationBadge(){try{const d=await api('/.netlify/functions/social-notifications');if(lastUnreadCount!==null&&d.unread_count>lastUnreadCount&&!document.hidden)playNotificationSound(notificationSoundChoice);lastUnreadCount=Number(d.unread_count||0);const b=document.getElementById('aamNotifyBtn');if(b)b.innerHTML='♢'+(d.unread_count?'<span class="aam-notify-count">'+d.unread_count+'</span>':'');}catch(e){}}
async function notifications(){loadingPage('Loading notifications…','profile');try{const d=await api('/.netlify/functions/social-notifications');mount('<div class="aam-social-card"><h2>Notifications</h2>'+(d.notifications||[]).map(n=>'<div class="aam-social-notification '+(n.read_at?'':'unread')+'">'+(n.actor?.avatar_url?'<img class="aam-notification-avatar" src="'+esc(n.actor.avatar_url)+'" alt="">':'')+'<strong>'+esc(n.actor?.display_name||'All Ads Manager')+'</strong><span>'+esc(n.title)+'</span><p>'+esc(n.body||'')+'</p><small>'+new Date(n.created_at).toLocaleString()+'</small></div>').join('')+(d.notifications?.length?'':'<p class="aam-social-muted">You have no notifications yet.</p>')+'</div>','profile');await api('/.netlify/functions/social-notifications','POST',{ids:(d.notifications||[]).map(n=>n.id)});updateNotificationBadge();}catch(e){notice(e.message);}}
async function chat(){loadingPage('Loading your chats…','chat');if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}document.body.classList.remove('aam-full-chat-open');try{const d=await api('/.netlify/functions/social-chat');mount('<div class="aam-social-card"><h2>Chats</h2><button class="aam-social-btn secondary" onclick="AAMSocial.messageAdmin()">Contact All Ads Manager</button>'+(d.conversations||[]).map(c=>'<button class="aam-social-chat-row" onclick="AAMSocial.openChat(&quot;'+esc(c.id)+'&quot;)"><strong>'+esc(c.other?.display_name||'Friend')+(c.other?.is_group?' · Community':'')+'</strong><small>'+(c.other?.is_group?formatCount(c.other.member_count)+' members · '+(c.other.group_role==='admin'?'Group admin':'Member'):(c.other?.last_seen_at&&Date.now()-new Date(c.other.last_seen_at).getTime()<120000?'Online':(c.other?.last_seen_at?'Last seen '+new Date(c.other.last_seen_at).toLocaleString():'Offline')))+'</small><span>'+(c.last_message?esc(c.last_message.body||'Media message'):'Start a conversation')+'</span>'+(c.unread_count?'<b class="aam-chat-unread-count">'+formatCount(c.unread_count)+'</b>':'')+'</button>').join('')+'<p class="aam-social-muted">To start a chat, open a friend’s post and tap Message.</p></div>','chat');}catch(e){mount('<div class="aam-social-card"><h2>Chats</h2><p>'+esc(e.message)+'</p></div>','chat');}}
function messageAdmin(){if(window.aamChatPresenceTimer){clearInterval(window.aamChatPresenceTimer);window.aamChatPresenceTimer=null;}if(window.aamChatRefreshTimer){clearInterval(window.aamChatRefreshTimer);window.aamChatRefreshTimer=null;window.aamActiveChatId=null;}if(typeof window.supportPage==='function')window.supportPage();else notice('Administrator contact is not available right now.');}
async function startChat(id){try{const d=await api('/.netlify/functions/social-chat','POST',{action:'start',target_customer_id:id});openChat(d.conversation_id);}catch(e){notice(e.message);}}
function chatMessageHtml(m){
 const mine=m.sender_id===customer(),deleted=!!m.deleted_at,grouped={};
 (m.reactions||[]).forEach(r=>{grouped[r.emoji]=(grouped[r.emoji]||0)+1;});
 const reactionHtml=Object.entries(grouped).map(([e,n])=>'<span class="aam-message-reaction">'+e+' '+n+'</span>').join('');
 const body=deleted?'<p class="aam-message-deleted">This message was deleted</p>':'<p>'+esc(m.body||((m.message_type==='voice')?'Voice note':'Media message'))+(m.edited_at?' <small>(edited)</small>':'')+'</p>';
 const viewOnce=m.view_once===true&&!deleted;
 const onceStatus=viewOnce?(mine?(m.viewed_at?'↗ View Once · Opened':'↗ View Once · Sent'):(m.viewed_at?'↗ Opened once':'<button type="button" class="aam-view-once-open" onclick="event.stopPropagation();AAMSocial.viewChatOnce(&quot;'+esc(m.id)+'&quot;)">↗ View once</button>')):'';
 const voiceAvatar=m.message_type==='voice'&&m.creator?.avatar_url?'<img class="aam-chat-voice-avatar" src="'+esc(m.creator.avatar_url)+'" alt="">':'';
 const media=deleted?'':(viewOnce?'':(m.message_type==='voice'&&m.media_url?'<div class="aam-chat-voice-media">'+voiceAvatar+'<audio controls preload="none" src="'+esc(m.media_url)+'"></audio></div>':m.message_type==='image'&&m.media_url?'<button type="button" class="aam-chat-photo-open" aria-label="View photo full screen" onclick="event.stopPropagation();AAMSocial.viewChatPhoto(&quot;'+esc(m.media_url)+'&quot;)"><img class="aam-social-chat-media" loading="lazy" src="'+esc(m.media_url)+'" alt="Shared image"></button>':m.message_type==='video'&&m.media_url?'<video class="aam-social-chat-media" controls playsinline preload="none" src="'+esc(m.media_url)+'"></video>':m.message_type==='shared_post'?'<button class="aam-social-btn secondary" onclick="event.stopPropagation();AAMSocial.viewSharedPost(&quot;'+esc(m.shared_post_id||'')+'&quot;)">View shared post</button>':''));
 const read=mine?(m.read_by?.length?'<small class="aam-read">READ</small>':'<i class="aam-unread-dot"></i>'):'';
 return '<div class="aam-social-message '+(mine?'mine':'')+'" data-message-id="'+esc(m.id)+'" data-state="'+esc(JSON.stringify(m))+'" onpointerdown="AAMSocial.beginMessagePress(event,&quot;'+esc(m.id)+'&quot;)" onpointermove="AAMSocial.moveMessagePress(event)" onpointerup="AAMSocial.endMessagePress(event)" onpointercancel="AAMSocial.cancelMessagePress(event)" oncontextmenu="event.preventDefault();return false"><strong>'+esc(m.creator?.display_name||'Friend')+'</strong>'+body+media+onceStatus+'<small>'+new Date(m.created_at).toLocaleString()+'</small>'+read+(reactionHtml?'<div class="aam-message-reactions">'+reactionHtml+'</div>':'')+'</div>';
}
let aamMessagePress=null;
function beginMessagePress(event,id){if(event.button!==undefined&&event.button!==0)return;if(event.target?.closest?.('button,video,audio'))return;cancelMessagePress();const state={id,x:event.clientX,y:event.clientY,timer:null};state.timer=setTimeout(()=>{aamMessagePress=null;window.aamSuppressMessageClickUntil=Date.now()+900;openMessageActions(null,id);},550);aamMessagePress=state;}
function moveMessagePress(event){if(!aamMessagePress)return;const dx=event.clientX-aamMessagePress.x,dy=event.clientY-aamMessagePress.y;if(Math.hypot(dx,dy)>12)cancelMessagePress();}
function endMessagePress(){if(!aamMessagePress)return;clearTimeout(aamMessagePress.timer);aamMessagePress=null;}
function cancelMessagePress(){if(aamMessagePress?.timer)clearTimeout(aamMessagePress.timer);aamMessagePress=null;}
function closeMessageActions(){document.getElementById('aamMessageActions')?.remove();}
function openMessageActions(event,id){if(Date.now()<(window.aamSuppressMessageClickUntil||0))return;if(event?.target?.closest?.('button,video,audio'))return;const m=window.aamChatMessages?.find(x=>x.id===id);if(!m)return;closeMessageActions();const mine=m.sender_id===customer(),editable=mine&&!m.deleted_at&&m.message_type==='text'&&(Date.now()-new Date(m.created_at).getTime()<900000);const panel=document.createElement('div');panel.id='aamMessageActions';panel.className='aam-message-actions';panel.innerHTML='<div class="aam-message-action-backdrop" onclick="AAMSocial.closeMessageActions()"></div><div class="aam-message-action-sheet"><div class="aam-message-reaction-picker">'+['👍','❤️','😂','😮','😢','🙏','🔥','👏','😍','🎉'].map(e=>'<button type="button" onclick="AAMSocial.reactToMessage(\''+id+'\',\''+e+'\')">'+e+'</button>').join('')+'</div><div class="aam-message-action-buttons">'+(editable?'<button type="button" onclick="AAMSocial.editChatMessage(\''+id+'\')">✎ Edit</button>':'')+(mine&&!m.deleted_at?'<button type="button" class="danger" onclick="AAMSocial.deleteChatMessage(\''+id+'\')">Delete</button>':'')+'<button type="button" onclick="AAMSocial.closeMessageActions()">Cancel</button></div>'+(mine&&m.message_type==='text'&&!m.deleted_at&&!editable?'<small>The 15-minute edit period has expired.</small>':'')+'</div>';document.body.appendChild(panel);}
async function reactToMessage(id,emoji){try{await api('/.netlify/functions/social-chat','POST',{action:'react_message',message_id:id,emoji});closeMessageActions();await refreshChatMessages(window.aamActiveChatId);}catch(e){notice(e.message);}}
async function editChatMessage(id){const m=window.aamChatMessages?.find(x=>x.id===id);if(!m)return closeMessageActions();if(Date.now()-new Date(m.created_at).getTime()>=900000){closeMessageActions();notice('The 15-minute edit period has expired.');return;}const value=prompt('Edit your message',m.body||'');if(value===null)return closeMessageActions();try{await api('/.netlify/functions/social-chat','POST',{action:'edit_message',message_id:id,body:value});closeMessageActions();await refreshChatMessages(window.aamActiveChatId);}catch(e){notice(e.message);}}
async function deleteChatMessage(id){if(!confirm('Delete this message for everyone?'))return;try{await api('/.netlify/functions/social-chat','POST',{action:'delete_message',message_id:id});closeMessageActions();await refreshChatMessages(window.aamActiveChatId);}catch(e){notice(e.message);}}
async function refreshChatMessages(id){try{if(window.aamActiveChatId!==id)return;const area=document.querySelector('.aam-social-chat-messages');if(!area)return;const nearBottom=area.scrollHeight-area.scrollTop-area.clientHeight<90;const viewportTop=area.getBoundingClientRect().top;const anchor=[...area.querySelectorAll('[data-message-id]')].find(el=>el.getBoundingClientRect().bottom>viewportTop);const anchorId=anchor?.dataset.messageId;const anchorTop=anchor?.getBoundingClientRect().top;const d=await api('/.netlify/functions/social-chat?conversation_id='+encodeURIComponent(id));if(window.aamActiveChatId!==id)return;const messages=d.messages||[];window.aamChatMessages=messages;for(const m of messages){const existing=area.querySelector('[data-message-id="'+m.id+'"]');if(!existing){area.insertAdjacentHTML('beforeend',chatMessageHtml(m));continue;}if(existing.dataset.state!==JSON.stringify(m)&&!existing.querySelector('audio:playing,video:playing')){const wrap=document.createElement('div');wrap.innerHTML=chatMessageHtml(m);existing.replaceWith(wrap.firstElementChild);}}if(nearBottom){area.scrollTop=area.scrollHeight;}else if(anchorId&&anchorTop!==undefined){const kept=area.querySelector('[data-message-id="'+anchorId+'"]');if(kept)area.scrollTop+=kept.getBoundingClientRect().top-anchorTop;}}catch(e){}}
async function openChat(id){mount('<section class="aam-social-card aam-social-chat-screen"><header class="aam-chat-header"><button class="aam-chat-back" onclick="AAMSocial.open(&quot;chat&quot;)" aria-label="Return to chats">‹</button><div class="aam-chat-heading"><strong class="aam-chat-title">Conversation</strong><small>All Ads Manager chat</small></div></header><div class="aam-social-chat-messages"><p class="aam-chat-opening">Opening conversation…</p></div></section>','chat');try{const [d,settings]=await Promise.all([api('/.netlify/functions/social-chat?conversation_id='+encodeURIComponent(id)),api('/.netlify/functions/social-core')]);const messages=d.messages||[];window.aamChatMessages=messages;window.aamChatOtherCustomerId=d.other_customer_id||null;const wallpaper='wallpaper-'+(settings.preferences?.chat_wallpaper||'default');const otherProfile=d.other_profile||null;const title=d.conversation?.title||otherProfile?.display_name||'Conversation';const initials=title.trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'A';mount('<section class="aam-social-card aam-social-chat-screen"><header class="aam-chat-header"><button class="aam-chat-back" onclick="AAMSocial.open(&quot;chat&quot;)" aria-label="Return to chats">‹</button>'+(otherProfile?.avatar_url?'<img class="aam-chat-avatar" src="'+esc(otherProfile.avatar_url)+'" alt="">':'<div class="aam-chat-avatar" aria-hidden="true">'+esc(initials)+'</div>')+'<div class="aam-chat-heading"><strong class="aam-chat-title">'+esc(title)+'</strong><small>All Ads Manager chat</small></div><button type="button" class="aam-chat-more" aria-label="Conversation details" onclick="AAMSocial.open(&quot;profile&quot;)">⋮</button></header><div class="aam-social-chat-messages '+wallpaper+'">'+messages.map(chatMessageHtml).join('')+'</div><div class="aam-chat-composer"><button type="button" class="aam-chat-attach" aria-label="Attach photo or video" onclick="document.getElementById(&quot;aamChatMedia&quot;).click()">＋</button><textarea id="aamChatBody" class="aam-social-field" maxlength="5000" rows="1" aria-label="Message" placeholder="Message" oninput="AAMSocial.updateComposer()" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();AAMSocial.sendChat(\''+esc(id)+'\')}"></textarea><button type="button" class="aam-chat-emoji" aria-label="Open emoji keyboard" onclick="AAMSocial.toggleChatEmoji()">☺</button><button type="button" class="aam-chat-camera" aria-label="Take photo" onclick="document.getElementById(&quot;aamChatCamera&quot;).click()">▣</button><button type="button" class="aam-chat-mic" aria-label="Record voice message" title="Tap to start or stop recording" onpointerdown="AAMSocial.beginVoiceHold(&quot;'+esc(id)+'&quot;,event)" onpointermove="AAMSocial.moveVoiceHold(event)" onpointerup="AAMSocial.endVoiceHold(event)" onpointercancel="AAMSocial.cancelVoiceGesture(event)" oncontextmenu="return false">🎙</button><button type="button" class="aam-chat-send" aria-label="Send message" onclick="AAMSocial.sendChat(&quot;'+esc(id)+'&quot;)">➤</button></div><div id="aamChatEmojiPanel" class="aam-chat-emoji-panel" hidden></div><div id="aamRecordingStatus" class="aam-chat-recording-status" aria-live="polite"></div><input class="aam-chat-media-input" id="aamChatMedia" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" onchange="AAMSocial.sendChatMedia(&quot;'+esc(id)+'&quot;)"><input class="aam-chat-media-input" id="aamChatCamera" type="file" accept="image/*" capture="environment" onchange="AAMSocial.sendChatMedia(&quot;'+esc(id)+'&quot;,this)"></section>','chat');const chatArea=document.querySelector('.aam-social-chat-messages');if(chatArea)chatArea.scrollTop=chatArea.scrollHeight;if(chatArea&&settings.preferences?.custom_wallpaper_url){chatArea.style.backgroundImage='url("'+settings.preferences.custom_wallpaper_url+'")';chatArea.style.backgroundSize='cover';chatArea.style.backgroundPosition='center';}if(window.aamChatPresenceTimer)clearInterval(window.aamChatPresenceTimer);if(window.aamChatRefreshTimer)clearInterval(window.aamChatRefreshTimer);window.aamActiveChatId=id;const touch=()=>api('/.netlify/functions/social-chat','POST',{action:'touch',conversation_id:id}).catch(()=>{});touch();window.aamChatPresenceTimer=setInterval(touch,30000);window.aamChatRefreshTimer=setInterval(()=>refreshChatMessages(id),4000);}catch(e){notice(e.message);}}
let voiceHold=null;
function voiceStatus(m,rec=false){const el=document.getElementById('aamRecordingStatus');if(el){el.textContent=m;el.classList.toggle('recording',rec);}}
function cancelVoiceOnExit(){const st=voiceHold;if(!st)return;st.cancelled=true;st.send=false;clearInterval(st.countdown);if(st.recorder&&st.recorder.state!=='inactive'){try{st.recorder.stop();}catch(_){st.stream?.getTracks().forEach(t=>t.stop());voiceHold=null;}}else{st.stream?.getTracks().forEach(t=>t.stop());if(st.objectUrl)URL.revokeObjectURL(st.objectUrl);voiceHold=null;}}
async function beginVoiceHold(id,e){if(e.button!==undefined&&e.button!==0)return;e.preventDefault();if(voiceHold)return;try{e.currentTarget.setPointerCapture(e.pointerId);}catch(_){}const st={id,pointerId:e.pointerId,x:e.clientX,y:e.clientY,locked:false,released:false,cancelled:false,started:false,send:false,recorder:null,stream:null,chunks:[],mime:'',blob:null,finalized:false,paused:false,preview:false,objectUrl:null};voiceHold=st;voiceStatus('Release to send · slide left to cancel · slide up to lock');try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Voice recording is not supported in this browser.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(voiceHold!==st||st.cancelled||st.released){stream.getTracks().forEach(t=>t.stop());if(voiceHold===st)voiceHold=null;voiceStatus('');return;}st.stream=stream;const supported=['audio/webm','audio/mp4'].filter(type=>{try{return MediaRecorder.isTypeSupported(type);}catch(_){return false;}});let rec=null;for(const type of supported){try{rec=new MediaRecorder(stream,{mimeType:type});break;}catch(_){}}if(!rec){try{rec=new MediaRecorder(stream);}catch(_){throw new Error('Voice recording is not supported in this browser.');}}st.mime=String(rec.mimeType||supported[0]||'').split(';')[0].trim().toLowerCase();if(!['audio/webm','audio/mp4'].includes(st.mime))throw new Error('This browser cannot record a supported voice-note format.');st.recorder=rec;st.started=true;rec.ondataavailable=x=>{if(x.data?.size)st.chunks.push(x.data);};rec.onstop=()=>voiceStopped(st);rec.start(250);let seconds=0;st.countdown=setInterval(()=>{seconds++;if(voiceHold!==st)return;voiceStatus('● Recording · '+(60-seconds)+'s'+(st.locked?' · Locked':''),true);if(seconds>=60){st.send=true;stopVoice(st);}},1000);voiceStatus('● Recording · 60s · slide left to cancel · slide up to lock',true);if(st.released&&!st.locked){st.send=true;stopVoice(st);}}catch(err){st.stream?.getTracks().forEach(t=>t.stop());if(voiceHold===st)voiceHold=null;voiceStatus('');notice(err.message);}}
function moveVoiceHold(e){const st=voiceHold;if(!st||st.pointerId!==e.pointerId||st.locked||st.released)return;const dx=e.clientX-st.x,dy=e.clientY-st.y;if(dx<-85){cancelVoiceGesture(e);return;}if(dy<-85){st.locked=true;try{e.currentTarget.releasePointerCapture(e.pointerId);}catch(_){}showLockedVoice(st);}}
function endVoiceHold(e){const st=voiceHold;if(!st||st.pointerId!==e.pointerId)return;st.released=true;if(!st.locked){st.send=true;if(st.started)stopVoice(st);else{st.cancelled=true;voiceHold=null;voiceStatus('');}}}
function cancelVoiceGesture(e){const st=voiceHold;if(!st||st.pointerId!==e.pointerId)return;st.cancelled=true;st.send=false;if(st.recorder&&st.recorder.state!=='inactive')stopVoice(st);else{st.stream?.getTracks().forEach(t=>t.stop());voiceHold=null;voiceStatus('');}}
function showLockedVoice(st){const el=document.getElementById('aamRecordingStatus');if(el)el.innerHTML='<div class="aam-voice-locked"><span>● Recording locked</span><button onclick="AAMSocial.toggleVoicePause()">'+(st.paused?'Resume':'Pause')+'</button><button onclick="AAMSocial.previewVoice()">Preview</button><button onclick="AAMSocial.cancelLockedVoice()">Delete</button><button onclick="AAMSocial.sendLockedVoice()">Send</button></div>';if(el)el.classList.add('recording');}
function toggleVoicePause(){const st=voiceHold;if(!st?.recorder||st.finalized)return;if(st.recorder.state==='recording'&&st.recorder.pause){st.recorder.pause();st.paused=true;}else if(st.recorder.state==='paused'){st.recorder.resume();st.paused=false;}showLockedVoice(st);}
function stopVoice(st){if(st?.recorder&&st.recorder.state!=='inactive')st.recorder.stop();}
function voiceStopped(st){clearInterval(st.countdown);st.stream?.getTracks().forEach(t=>t.stop());st.blob=new Blob(st.chunks,{type:st.mime});st.finalized=true;if(st.cancelled){if(voiceHold===st)voiceHold=null;voiceStatus('Recording cancelled.');setTimeout(()=>voiceStatus(''),1000);return;}if(st.preview){st.objectUrl=URL.createObjectURL(st.blob);const el=document.getElementById('aamRecordingStatus');if(el)el.innerHTML='<div class="aam-voice-preview"><audio controls src="'+st.objectUrl+'"></audio><div class="aam-voice-locked"><button onclick="AAMSocial.cancelLockedVoice()">Delete</button><button onclick="AAMSocial.sendLockedVoice()">Send voice note</button></div></div>';return;}if(st.send)uploadVoice(st);}
function previewVoice(){const st=voiceHold;if(!st)return;if(!st.finalized){st.preview=true;stopVoice(st);return;}if(st.objectUrl){const el=document.getElementById('aamRecordingStatus');if(el)el.innerHTML='<audio controls autoplay src="'+st.objectUrl+'"></audio><div class="aam-voice-locked"><button onclick="AAMSocial.cancelLockedVoice()">Delete</button><button onclick="AAMSocial.sendLockedVoice()">Send voice note</button></div>';}}
async function uploadVoice(st){if(!st||st.uploading||!st.blob)return;st.uploading=true;voiceStatus('Sending voice note…');try{const signed=await api('/.netlify/functions/social-chat','POST',{action:'sign_voice_upload',mime_type:st.mime});const uploaded=await socialDb.storage.from('aam-social-voice').uploadToSignedUrl(signed.path,signed.token,st.blob,{contentType:st.mime,upsert:false});if(uploaded.error)throw uploaded.error;await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:st.id,message_type:'voice',body:'Voice note',media_path:signed.path});if(st.objectUrl)URL.revokeObjectURL(st.objectUrl);if(voiceHold===st)voiceHold=null;voiceStatus('');await refreshChatMessages(st.id);}catch(err){st.uploading=false;notice(err.message||'Voice note could not be sent. Please try again.');const el=document.getElementById('aamRecordingStatus');if(el){el.innerHTML='<div class="aam-voice-preview">'+(st.objectUrl?'<audio controls src="'+esc(st.objectUrl)+'"></audio>':'<span>Voice note is ready to send.</span>')+'<small>Sending failed. Your recording is saved here.</small><div class="aam-voice-locked"><button onclick="AAMSocial.cancelLockedVoice()">Delete</button><button onclick="AAMSocial.sendLockedVoice()">Try again</button></div></div>';el.classList.add('recording');}}}
function sendLockedVoice(){const st=voiceHold;if(!st)return;st.send=true;if(st.finalized)uploadVoice(st);else stopVoice(st);}
function cancelLockedVoice(){const st=voiceHold;if(!st)return;st.cancelled=true;st.send=false;if(st.recorder&&st.recorder.state!=='inactive')stopVoice(st);else{clearInterval(st.countdown);st.stream?.getTracks().forEach(t=>t.stop());if(st.objectUrl)URL.revokeObjectURL(st.objectUrl);voiceHold=null;voiceStatus('');}}
async function copySocialText(value){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(String(value));notice('Copied.');return;}const t=document.createElement('textarea');t.value=String(value);t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();notice('Copied.');}catch(e){notice('Could not copy this item.');}}
async function copyProfileId(){const id=document.getElementById('aamProfileId')?.value||'';if(id)await copySocialText(id);}
async function copyProfileLink(){const url=document.getElementById('aamProfileUrl')?.value||'';if(url)await copySocialText(url);}
async function shareProfile(){const url=document.getElementById('aamProfileUrl')?.value||'';if(!url)return notice('Profile link is unavailable.');try{if(navigator.share)await navigator.share({title:'All Ads Manager profile',url});else await copySocialText(url);}catch(e){if(e.name!=='AbortError')await copySocialText(url);}}
async function sharePostLink(id){const url=window.location.origin+'/?post='+encodeURIComponent(id);try{if(navigator.share)await navigator.share({title:'All Ads Manager post',url});else await copySocialText(url);}catch(e){if(e.name!=='AbortError')await copySocialText(url);}}
async function sharePost(postId){try{const d=await api('/.netlify/functions/social-chat'),list=d.conversations||[];if(!list.length)return notice('Start a chat with a friend before sharing a post.');const choices=list.map((c,i)=>(i+1)+'. '+(c.other?.display_name||'Friend')).join('\n');const pick=Number(prompt('Share this post with which chat?\n'+choices));if(!Number.isInteger(pick)||pick<1||pick>list.length)return;const conversation=list[pick-1];await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:conversation.id,message_type:'shared_post',shared_post_id:postId,body:''});notice('Post shared.');openChat(conversation.id);}catch(e){notice(e.message);}}
async function viewSharedPost(postId){loadingPage('Opening shared post…','chat');try{const d=await api('/.netlify/functions/social-feed'),p=(d.posts||[]).find(x=>x.id===postId);if(!p)return notice('This shared post is no longer available in the current feed.');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.open(&quot;chat&quot;)">← Chats</button><h2>Shared post</h2>'+postCard(p)+'</div>','chat');}catch(e){notice(e.message);}}
let photoDraft=null,photoCanvas=null,photoCtx=null,photoHistory=[],photoMode='pen',photoColorValue='#ff3030',photoDrawing=false,photoStart=null,photoCrop=null;
function chatOverlay(){let o=document.getElementById('aamChatOverlay');if(!o){o=document.createElement('div');o.id='aamChatOverlay';document.body.appendChild(o);}return o;}
function viewChatPhoto(url){
 const o=chatOverlay();o.className='aam-chat-viewer';
 o.innerHTML='<button class="aam-viewer-close" aria-label="Close photo" onclick="AAMSocial.closeChatOverlay()">×</button><div class="aam-viewer-stage"><img id="aamViewerImage" draggable="false" src="'+esc(url)+'" alt="Photo"></div>';
 const img=o.querySelector('img');img.addEventListener('dragstart',e=>e.preventDefault());
 window.aamViewerEscape=e=>{if(e.key==='Escape')closeChatOverlay();};document.addEventListener('keydown',window.aamViewerEscape);
}
function zoomChatPhoto(f){if(window.aamViewerZoom)window.aamViewerZoom(f);}
function togglePhotoViewOnce(){if(!photoDraft)return;photoDraft.viewOnce=!photoDraft.viewOnce;const b=document.querySelector('.aam-view-once-toggle');if(b){b.classList.toggle('active',photoDraft.viewOnce);b.setAttribute('aria-pressed',String(photoDraft.viewOnce));b.textContent=photoDraft.viewOnce?'↗ 1 · ON':'↗ 1';}}
async function viewChatOnce(id){try{const d=await api('/.netlify/functions/social-chat','POST',{action:'view_once',message_id:id});const o=chatOverlay();o.className='aam-chat-viewer aam-chat-view-once';o.innerHTML='<button class="aam-viewer-close" aria-label="Close view-once media" onclick="AAMSocial.closeChatOverlay()">×</button>'+(d.message_type==='video'?'<video class="aam-view-once-media" autoplay playsinline controls src="'+esc(d.media_url)+'"></video>':'<img class="aam-view-once-media" draggable="false" src="'+esc(d.media_url)+'" alt="View-once photo">');const media=o.querySelector('video');if(media)media.addEventListener('ended',closeChatOverlay,{once:true});await refreshChatMessages(window.aamActiveChatId);}catch(e){notice(e.message||'This view-once message has already been opened.');await refreshChatMessages(window.aamActiveChatId);}}

function closeChatOverlay(){const o=document.getElementById('aamChatOverlay');if(o){o.className='';o.innerHTML='';}if(window.aamViewerEscape){document.removeEventListener('keydown',window.aamViewerEscape);window.aamViewerEscape=null;}window.aamViewerScale=1;window.aamViewerReset=null;}
function sendChatMedia(id,source){const input=source||document.getElementById('aamChatMedia'),file=input?.files?.[0];if(!file)return;if(file.type.startsWith('video/')){openVideoDraft(id,file,input);return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){notice('Choose a supported photo or video.');return;}openPhotoEditor(id,file,input);}
function openVideoDraft(id,file,input){const url=URL.createObjectURL(file),o=chatOverlay();photoDraft={id,file,input,url,video:true,viewOnce:false};o.className='aam-chat-editor';o.innerHTML='<header><button onclick="AAMSocial.cancelPhotoDraft()">Cancel</button><strong>Preview video</strong><button type="button" class="aam-view-once-toggle" aria-pressed="false" onclick="AAMSocial.togglePhotoViewOnce()">↗ 1</button><button onclick="AAMSocial.confirmPhotoSend()">Send</button></header><div class="aam-editor-stage"><video controls playsinline src="'+url+'"></video></div><input class="aam-editor-caption" id="aamEditorCaption" maxlength="1000" placeholder="Add a caption…">';}
function openPhotoEditor(id,file,input){const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const o=chatOverlay();photoDraft={id,file,input,url,video:false,viewOnce:false};photoHistory=[];photoMode='pen';photoCrop=null;o.className='aam-chat-editor';o.innerHTML='<header><button onclick="AAMSocial.cancelPhotoDraft()">Cancel</button><strong>Edit photo</strong><button type="button" class="aam-view-once-toggle" aria-pressed="false" onclick="AAMSocial.togglePhotoViewOnce()">↗ 1</button><button onclick="AAMSocial.confirmPhotoSend()">Send</button></header><div class="aam-editor-stage"><div class="aam-editor-canvas-wrap"><canvas id="aamPhotoCanvas"></canvas><div id="aamPhotoCropBox" class="aam-photo-crop-box" hidden></div></div></div><div class="aam-editor-tools"><button onclick="AAMSocial.photoTool(\'crop\')">Crop</button><button onclick="AAMSocial.photoTool(\'pen\')">Draw</button><button onclick="AAMSocial.undoPhotoEdit()">Undo</button><button onclick="AAMSocial.rotatePhoto()">Rotate</button><button style="background:#ff3030" onclick="AAMSocial.photoColor(\'#ff3030\')"></button><button style="background:#1687ff" onclick="AAMSocial.photoColor(\'#1687ff\')"></button><button style="background:#20b45a" onclick="AAMSocial.photoColor(\'#20b45a\')"></button><button style="background:#ffd21f" onclick="AAMSocial.photoColor(\'#ffd21f\')"></button><button style="background:#fff" onclick="AAMSocial.photoColor(\'#ffffff\')"></button></div><input class="aam-editor-caption" id="aamEditorCaption" maxlength="1000" placeholder="Add a caption…"><p class="aam-editor-hint" id="aamEditorHint">Draw with your finger, or choose Crop and drag over the area to keep.</p>';photoCanvas=document.getElementById('aamPhotoCanvas');photoCanvas.width=img.naturalWidth;photoCanvas.height=img.naturalHeight;photoCtx=photoCanvas.getContext('2d');photoCtx.drawImage(img,0,0);savePhotoHistory();photoCanvas.addEventListener('pointerdown',photoPointerDown);photoCanvas.addEventListener('pointermove',photoPointerMove);photoCanvas.addEventListener('pointerup',photoPointerUp);photoCanvas.addEventListener('pointercancel',photoPointerUp);};img.onerror=()=>notice('Could not open this photo.');img.src=url;}
function savePhotoHistory(){if(photoCanvas){photoHistory.push(photoCtx.getImageData(0,0,photoCanvas.width,photoCanvas.height));if(photoHistory.length>15)photoHistory.shift();}}
function photoTool(mode){photoMode=mode;const h=document.getElementById('aamEditorHint');if(mode==='crop'&&photoCrop){const r=photoCrop,x=Math.max(0,Math.floor(r.x)),y=Math.max(0,Math.floor(r.y)),w=Math.min(photoCanvas.width-x,Math.floor(r.w)),hh=Math.min(photoCanvas.height-y,Math.floor(r.h));if(w>8&&hh>8){const d=photoCtx.getImageData(x,y,w,hh);photoCanvas.width=w;photoCanvas.height=hh;photoCtx.putImageData(d,0,0);savePhotoHistory();}photoCrop=null;photoMode='pen';const box=document.getElementById('aamPhotoCropBox');if(box)box.hidden=true;if(h)h.textContent='Crop applied.';}else if(h)h.textContent=mode==='crop'?'Drag over the area to keep, then tap Crop again.':'Draw on the photo with your finger.';}
function photoColor(c){photoColorValue=c;photoMode='pen';}
function photoPoint(e){const r=photoCanvas.getBoundingClientRect();return{x:(e.clientX-r.left)*photoCanvas.width/r.width,y:(e.clientY-r.top)*photoCanvas.height/r.height};}
function photoPointerDown(e){e.preventDefault();photoCanvas.setPointerCapture(e.pointerId);photoDrawing=true;photoStart=photoPoint(e);if(photoMode==='pen'){savePhotoHistory();photoCtx.beginPath();photoCtx.moveTo(photoStart.x,photoStart.y);photoCtx.strokeStyle=photoColorValue;photoCtx.lineWidth=Math.max(5,photoCanvas.width/150);photoCtx.lineCap='round';photoCtx.lineJoin='round';}}
function photoPointerMove(e){if(!photoDrawing)return;const p=photoPoint(e);if(photoMode==='pen'){photoCtx.lineTo(p.x,p.y);photoCtx.stroke();}else{photoCrop={x:Math.min(photoStart.x,p.x),y:Math.min(photoStart.y,p.y),w:Math.abs(p.x-photoStart.x),h:Math.abs(p.y-photoStart.y)};const box=document.getElementById('aamPhotoCropBox');if(box){box.hidden=false;box.style.left=(photoCrop.x/photoCanvas.width*100)+'%';box.style.top=(photoCrop.y/photoCanvas.height*100)+'%';box.style.width=(photoCrop.w/photoCanvas.width*100)+'%';box.style.height=(photoCrop.h/photoCanvas.height*100)+'%';}}}
function photoPointerUp(){if(photoDrawing){photoDrawing=false;const h=document.getElementById('aamEditorHint');if(photoMode==='crop'&&h)h.textContent='Tap Crop again to apply the selected area.';}}
function undoPhotoEdit(){if(photoHistory.length<2)return;photoHistory.pop();const d=photoHistory[photoHistory.length-1];photoCanvas.width=d.width;photoCanvas.height=d.height;photoCtx=photoCanvas.getContext('2d');photoCtx.putImageData(d,0,0);}
function rotatePhoto(){const c=document.createElement('canvas');c.width=photoCanvas.height;c.height=photoCanvas.width;const x=c.getContext('2d');x.translate(c.width/2,c.height/2);x.rotate(Math.PI/2);x.drawImage(photoCanvas,-photoCanvas.width/2,-photoCanvas.height/2);photoCanvas.width=c.width;photoCanvas.height=c.height;photoCtx=photoCanvas.getContext('2d');photoCtx.drawImage(c,0,0);savePhotoHistory();}
function cancelPhotoDraft(){if(photoDraft?.url)URL.revokeObjectURL(photoDraft.url);if(photoDraft?.input)photoDraft.input.value='';photoDraft=null;photoCanvas=null;closeChatOverlay();}
async function confirmPhotoSend(){const d=photoDraft;if(!d)return;const btn=document.querySelector('.aam-chat-editor header button:last-child');if(btn){btn.disabled=true;btn.textContent='Sending…';}try{let file=d.file;if(!d.video){const blob=await new Promise((res,rej)=>photoCanvas.toBlob(b=>b?res(b):rej(new Error('Could not prepare photo.')),'image/jpeg',.92));file=new File([blob],'chat-photo.jpg',{type:'image/jpeg'});}const signed=await api('/.netlify/functions/social-chat','POST',{action:'sign_media_upload',mime_type:file.type});const uploaded=await socialDb.storage.from('aam-social-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;await api('/.netlify/functions/social-chat','POST',{action:'send',conversation_id:d.id,message_type:signed.message_type,media_path:signed.path,body:document.getElementById('aamEditorCaption')?.value||'',view_once:d.viewOnce===true});if(d.input)d.input.value='';cancelPhotoDraft();await refreshChatMessages(d.id);}catch(e){notice(e.message);if(btn){btn.disabled=false;btn.textContent='Send';}}}

