const adminToken=()=>sessionStorage.getItem('btAdminToken');
const adminApi=async(method='GET',body)=>{const url='/.netlify/functions/social-admin'+(method==='GET'?'?token='+encodeURIComponent(adminToken()):'');const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify({...body,token:adminToken()})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Administrator social action failed.');return d;};

async function openAdminPromotions(){loadingPage('Loading promotions…','profile');try{const r=await fetch('/.netlify/functions/social-promotion-admin?token='+encodeURIComponent(adminToken()));const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load promotions.');const cards=(d.promotions||[]).map(p=>'<article class="aam-social-card"><div class="aam-social-muted">PROMOTION · '+esc(p.status.replaceAll('_',' '))+'</div><h3>'+esc(p.title)+'</h3><p>Customer: <strong>'+esc(p.customer_name)+'</strong></p><img class="aam-social-preview" src="'+esc(p.media_url)+'" alt="Customer advert"><p>'+esc(p.description)+'</p><p>Type: '+esc(p.promotion_type)+' · Requested: '+Number(p.requested_days)+' days</p><p>Provider status: '+esc(p.provider_status.replaceAll('_',' '))+'</p>'+(p.status==='pending_review'?'<label>Price in Money Coins</label><input class="aam-social-field" type="number" min="1" id="aamPromoPrice_'+p.id+'" placeholder="Set price after provider is connected"><label>Admin note</label><input class="aam-social-field" id="aamPromoNote_'+p.id+'" maxlength="500" placeholder="Review note"><button class="aam-social-btn" '+(p.provider_status==='ready'?'':'disabled')+' onclick="AAMSocial.adminPromotionPrice(\''+p.id+'\')">Approve and set price</button><button class="aam-social-btn secondary" onclick="AAMSocial.adminPromotionReject(\''+p.id+'\')">Reject advert</button>' : (p.price_coins?'<p>Price: '+Number(p.price_coins).toLocaleString()+' Money Coins</p>':'')+(p.admin_note?'<p>Note: '+esc(p.admin_note)+'</p>':''))+'</article>').join('');mount('<div class="aam-social-card"><button class="aam-social-btn secondary" onclick="AAMSocial.admin()">← Admin dashboard</button><h2>Manager Promotion review</h2><p class="aam-social-muted">Provider connection: not verified. Pricing and payment remain disabled until the provider is genuinely connected.</p></div>'+(cards||'<div class="aam-social-card">No promotion submissions yet.</div>'),'profile');}catch(e){notice(e.message);}}
async function adminPromotionPrice(id){const price=Number(document.getElementById('aamPromoPrice_'+id)?.value),note=document.getElementById('aamPromoNote_'+id)?.value||'';if(!Number.isSafeInteger(price)||price<1)return notice('Enter a valid Money Coin price.');try{const r=await fetch('/.netlify/functions/social-promotion-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:adminToken(),action:'set_price',promotion_id:id,price_coins:price,admin_note:note})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not approve promotion.');notice('Price saved.');openAdminPromotions();}catch(e){notice(e.message);}}
async function adminPromotionReject(id){const note=prompt('Reason for rejecting this advert:');if(note===null)return;try{const r=await fetch('/.netlify/functions/social-promotion-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:adminToken(),action:'reject',promotion_id:id,admin_note:note})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not reject promotion.');notice('Advert rejected.');openAdminPromotions();}catch(e){notice(e.message);}}
async function admin(){if(!adminToken())return notice('Administrator login required.');loadingPage('Loading social management…','profile');try{const d=await adminApi();const p=d.profile||{},a=d.coin_accounting||{};mount('<div class="aam-social-card"><h2>Manager Promotion</h2><p>Review customer adverts and provider readiness.</p><button class="aam-social-btn" onclick="AAMSocial.openAdminPromotions()">Review promotions</button></div><div class="aam-social-card"><h2>Social profile settings</h2><button class="aam-social-btn secondary" onclick="window.enableAppNotifications?.()">Turn on administrator alerts</button><label>Friend profile picture</label><input id="aamAdminAvatar" class="aam-social-field" type="file" accept="image/jpeg,image/png,image/webp"><button class="aam-social-btn secondary" onclick="AAMSocial.adminAvatar()">Update creator picture</button><label>Creator display name</label><input id="aamAdminName" class="aam-social-field" maxlength="40" value="'+esc(p.display_name||'All Ads Manager')+'"><label>Follower count (0–100,000,000)</label><input id="aamAdminFollowers" class="aam-social-field" type="number" min="0" max="100000000" value="'+Number(p.follower_count||0)+'"><button class="aam-social-btn" onclick="AAMSocial.adminSave()">Save friend profile</button><p class="aam-social-muted">Verified badge is enabled. Likes display as 3.5K and following as 0.</p></div><div class="aam-social-card"><h3>Coin accounting</h3><p>Verified Paystack coin sales: <strong>₦'+Number(a.verified_coin_sales_naira||0).toLocaleString()+'</strong></p><p>Money Coins sold: '+Number(a.verified_coins_sold||0).toLocaleString()+'</p><p>Admin earnings from purchased coins spent on video views: <strong>₦'+Number(a.video_earnings_naira||0).toLocaleString()+'</strong></p><p>Free coins outstanding: '+Number(a.free_coins_outstanding||0).toLocaleString()+' · Money Coins outstanding: '+Number(a.purchased_coins_outstanding||0).toLocaleString()+'</p><p class="aam-social-muted">Free rewards are excluded from money totals.</p></div><div class="aam-social-card"><h3>Publish as All Ads Manager</h3><input id="aamAdminMedia" class="aam-social-field" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" onchange="AAMSocial.previewAdminSource()">'+soundPickerMarkup('admin')+'<div id="aamAdminLockOption" class="aam-social-muted" hidden><label class="aam-social-check"><input id="aamAdminLockVideo" type="checkbox"> Mark this administrator video as paid (1 viewing coin / ₦1 per view)</label><small>Leave unchecked to make this video free. API-sourced videos, customer-uploaded videos and all pictures are always free.</small></div><div id="aamAdminAudioEditor" class="aam-social-audio-editor"><video id="aamAdminSourcePreview" class="aam-social-preview" controls playsinline preload="metadata"></video><label class="aam-social-check"><input id="aamKeepOriginalAudio" type="checkbox" checked> Keep original video sound</label><label class="aam-social-check"><input id="aamRecordVoiceOver" type="checkbox"> Record my voice over the video</label><label>My voice volume <span id="aamVoiceVolumeValue">100%</span></label><input id="aamVoiceVolume" type="range" min="0" max="200" value="100" oninput="AAMSocial.audioVolumeLabel(\'voice\',this.value)"><label>Background music</label><input id="aamBackgroundMusic" class="aam-social-field" type="file" accept="audio/*"><label>Background music volume <span id="aamMusicVolumeValue">25%</span></label><input id="aamMusicVolume" type="range" min="0" max="100" value="25" oninput="AAMSocial.audioVolumeLabel(\'music\',this.value)"><div class="aam-social-actions"><button class="aam-social-btn secondary" type="button" onclick="AAMSocial.recordVideoMix()">Record voice-over / music mix</button><button class="aam-social-btn secondary" type="button" onclick="AAMSocial.stopVideoMix()">Stop recording</button></div><p id="aamVideoMixStatus" class="aam-social-muted">Choose a video to preview. You can keep original sound, mute it, add your voice, add music, and preview the finished mix before publishing.</p><video id="aamAdminMixedPreview" class="aam-social-preview" controls playsinline hidden></video></div><textarea id="aamAdminCaption" class="aam-social-field" maxlength="2200" placeholder="Write a caption…"></textarea><button class="aam-social-btn" onclick="AAMSocial.adminPublish()">Publish post</button></div><div class="aam-social-card"><h3>Community group members</h3><p class="aam-social-muted">Every customer is added automatically. Group roles are separate from platform administrator access.</p>'+(d.group_members||[]).map(m=>'<div class="aam-social-discover-row"><strong>'+esc(m.name)+'</strong><span class="aam-social-muted">'+esc(m.group_role)+'</span><button class="aam-social-btn secondary" onclick="AAMSocial.groupRole(&quot;'+esc(m.customer_id)+'&quot;,'+(m.group_role!=='admin')+')">'+(m.group_role==='admin'?'Remove group admin':'Appoint group admin')+'</button></div>').join('')+'</div><div class="aam-social-card"><h3>Social posts</h3>'+(d.posts||[]).map(p=>'<div class="aam-social-discover-row"><strong>'+esc(p.media_type==='video'?'Video':'Picture')+'</strong><p>'+esc(p.caption||'')+'</p><small>'+new Date(p.created_at).toLocaleString()+'</small><button class="aam-social-btn secondary" onclick="AAMSocial.adminDeletePost(&quot;'+esc(p.id)+'&quot;)">Remove post</button></div>').join('')+'</div><div class="aam-social-card"><h3>Recent comments</h3>'+(d.comments||[]).map(c=>'<div class="aam-social-discover-row"><strong>'+esc(c.creator_name||'Friend')+'</strong><p>'+esc(c.body)+'</p><button class="aam-social-btn secondary" onclick="AAMSocial.adminDeleteComment(&quot;'+esc(c.id)+'&quot;)">Delete comment</button></div>').join('')+'</div>','profile');}catch(e){notice(e.message);}}
async function groupRole(id,makeAdmin){try{await adminApi('POST',{action:'group_set_admin',customer_id:id,make_admin:makeAdmin});notice(makeAdmin?'Group administrator appointed.':'Group administrator role removed.');admin();}catch(e){notice(e.message);}}
async function adminAvatar(){const file=document.getElementById('aamAdminAvatar')?.files?.[0];if(!file)return notice('Choose a profile picture first.');try{const signed=await adminApi('POST',{action:'sign_upload',mime_type:file.type});await uploadSocialMedia(signed,file);await adminApi('POST',{action:'set_avatar',avatar_path:signed.path});notice('Creator picture updated.');admin();}catch(e){notice(e.message);}}
