const aamActionLocks=new Set();
const guardAamAction=(name,fn)=>function(...args){
 const perItem=['payPromotion','sendChat','sendChatMedia','comment','follow','like','adminPromotionPrice','adminPromotionReject'].includes(name);
 const key=perItem?name+':'+String(args[0]??''):name;
 if(aamActionLocks.has(key)){notice('This action is already in progress. Please wait.');return;}
 aamActionLocks.add(key);
 let result;
 try{result=fn.apply(this,args);}catch(error){aamActionLocks.delete(key);throw error;}
 if(result&&typeof result.finally==='function')return result.finally(()=>aamActionLocks.delete(key));
 aamActionLocks.delete(key);return result;
};
